var lab: Node = get_tree().current_scene
var regions: Array = []
for id: StringName in lab.manager.object_ids():
	var body: Node = lab.manager.get_body(id)
	var enabled: int = 0
	for shape: CollisionShape2D in body.colliders:
		if not shape.disabled: enabled += 1
	regions.append({"id":id,"logical_id":body.structure_id,"material":body.material_kind,"layer":body.collision_layer,"shapes":body.colliders.size(),"enabled_shapes":enabled,"builds":body.shape_builds,"script":body.get_script().resource_path})
var players: Array = []
for player: Node in lab.players:
	players.append({"id":player.player_id,"controller":player.get_script().resource_path,"mask":player.collision_mask,"on_floor":player.is_on_floor(),"adapter":player.material_adapter.get_script().resource_path})
return {"scene":lab.scene_file_path,"regions":regions,"logical_ids":lab.adapter.logical_active.keys(),"players":players,"physics_ticks_per_second":Engine.physics_ticks_per_second,"udp_receivers":get_tree().get_nodes_in_group("structure_udp_receivers").size()}
